f=summarize(dir:$str):i64{
  let entries=file.list(dir)|{
    Ok:e  e;
    Err:e @()
  };

  let total=mut.0;
  lp(let i=0;i<entries.len;i=i+1){
    let name=entries.get(i)|{Ok:v v;Err:e ""};
    let path=str.concat(dir;str.concat("/";name));
    let r=file.read(path);
