m=scores;
i=str:std.str;

f=topScore(board:@($str:i64)):i64{
  let best=mut.0;
  lp(let i=0 as u64;i<board.len;i=i+1 as u64){
    let v = board.get(str.fromInt(i as i64));
    if(v>best){ best=v; };
  };
  < best
};

